# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMP-000001",
    "name": "Dariush داریوش",
    "kind": "first-name",
    "meaning": "Dariush (داریوش) is a masculine given name in Persian. Meaning: Possessing goodness. From Old Persian Darayavaush; borne"
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Dar")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

